export type ParsedBuyListedPutInstruction<
  TProgram extends string = typeof ONCE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    buyer: TAccountMetas[0];
    config: TAccountMetas[1];
    put: TAccountMetas[2];
    listing: TAccountMetas[3];
    seller: TAccountMetas[4];
    usdcMint: TAccountMetas[5];
    usdcTokenProgram: TAccountMetas[6];
    paymentSource: TAccountMetas[7];
    paymentDestination: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: BuyListedPutInstructionData;
};

export function parseBuyListedPutInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBuyListedPutInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      buyer: getNextAccount(),
      config: getNextAccount(),
      put: getNextAccount(),
      listing: getNextAccount(),
      seller: getNextAccount(),
      usdcMint: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      paymentSource: getNextAccount(),
      paymentDestination: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getBuyListedPutInstructionDataDecoder().decode(instruction.data),
  };
}
